let activeLang = localStorage.getItem('tut_lang') || 'en';

function tr(s){
  if(!s) return s;
  const key=String(s).trim();
  return activeLang==='en' ? key : ((UI_TRANSLATIONS[activeLang]||{})[key] || key);
}
function translateNodeTree(root=document.body){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];
  while(walker.nextNode()) nodes.push(walker.currentNode);
  for(const n of nodes){
    const raw=n.__tutOriginalText ?? n.nodeValue;
    if(n.__tutOriginalText===undefined) n.__tutOriginalText=raw;
    const trimmed=String(raw).trim();
    if(!trimmed) continue;
    const translated=tr(trimmed);
    if(translated!==trimmed){
      const lead=String(raw).match(/^\s*/)?.[0]||'';
      const tail=String(raw).match(/\s*$/)?.[0]||'';
      n.nodeValue=lead+translated+tail;
    } else n.nodeValue=raw;
  }
  root.querySelectorAll?.('input[placeholder],textarea[placeholder]').forEach(el=>{
    if(!el.dataset.tutPlaceholder) el.dataset.tutPlaceholder=el.getAttribute('placeholder')||'';
    const p=el.dataset.tutPlaceholder;
    el.setAttribute('placeholder',tr(p));
  });
  root.querySelectorAll?.('[title]').forEach(el=>{
    if(!el.dataset.tutTitle) el.dataset.tutTitle=el.getAttribute('title')||'';
    el.setAttribute('title',tr(el.dataset.tutTitle));
  });
}
function refreshLanguage(){
  document.documentElement.lang=activeLang;
  document.documentElement.dir=activeLang==='ar'?'rtl':'ltr';
  translateNodeTree(document.body);
  const sel=document.getElementById('lang'); if(sel) sel.value=activeLang;
}

