function currencyFor(c){if(c==='Canada')return'CAD';if(c==='United Kingdom')return'GBP';if(c==='United Arab Emirates')return'AED';if(c==='Saudi Arabia')return'SAR';if(c==='Qatar')return'QAR';if(['United States'].includes(c))return'USD';return'EUR'}
function setIntent(v){$('intent').value=v;$('haveBtn').classList.toggle('active',v==='have');$('needBtn').classList.toggle('active',v==='need');renderFields()}
let activeMaps=[];
function destroyActiveMaps(){for(const m of activeMaps){try{m.remove()}catch{}}activeMaps=[]}
function fld(k,label,type='text',ph='',extra=''){return `<div class="field"><label>${tr(label)}</label><input data-k="${k}" type="${type}" placeholder="${esc(tr(ph))}" ${extra}></div>`}
function sel(k,label,options){return `<div class="field"><label>${tr(label)}</label><select data-k="${k}">${options.map(x=>`<option value="${esc(x)}">${tr(x)}</option>`).join('')}</select></div>`}
function checks(k,label,items){return `<fieldset class="specChecks" data-check-key="${k}"><legend>${tr(label)}</legend>${items.map(x=>`<label><input type="checkbox" value="${esc(x)}"> ${tr(x)}</label>`).join('')}</fieldset>`}
function mapWidget(key,label,placeholder){return `<div class="mapField"><label>${tr(label)}</label><div class="locationSearch"><input data-k="${key}" id="addr_${key}" placeholder="${esc(tr(placeholder))}"><button type="button" class="outlineBtn mini" onclick="searchAddress('${key}')">${tr('Find on map')}</button></div><input data-k="${key}Lat" id="lat_${key}" type="hidden"><input data-k="${key}Lng" id="lng_${key}" type="hidden"><div id="map_${key}" class="listingMap"></div><small>${tr('Type any address or click the map to set the exact point.')}</small></div>`}
function initListingMap(key){if(typeof L==='undefined')return;const el=$('map_'+key);if(!el)return;const m=L.map(el,{scrollWheelZoom:false}).setView([30,10],2);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(m);let marker=null;function setPoint(lat,lng){$('lat_'+key).value=Number(lat).toFixed(6);$('lng_'+key).value=Number(lng).toFixed(6);if(marker)marker.setLatLng([lat,lng]);else marker=L.marker([lat,lng]).addTo(m)}m.on('click',e=>setPoint(e.latlng.lat,e.latlng.lng));m.__setPoint=(lat,lng,label)=>{setPoint(lat,lng);m.setView([lat,lng],14);if(label)$('addr_'+key).value=label};activeMaps.push(m);setTimeout(()=>m.invalidateSize(),50)}
async function searchAddress(key){const q=$('addr_'+key)?.value?.trim();if(!q)return;const btn=document.activeElement;try{if(btn)btn.disabled=true;const r=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(q),{headers:{'Accept':'application/json'}});const a=await r.json();if(!a.length){alert(tr('Location not found. Try a more complete address.'));return}const m=activeMaps.find(x=>x.getContainer().id==='map_'+key);if(m)m.__setPoint(Number(a[0].lat),Number(a[0].lon),a[0].display_name)}catch(e){alert(tr('Map search is temporarily unavailable. You can still type the address and click the map.'))}finally{if(btn)btn.disabled=false}}
function categoryFields(r,intent){
 const available=intent==='have';
 if(r==='driver')return `<div class="formSection"><h3>${tr('Driver / operator profile')}</h3><div class="two">${fld('licenseClass','Licence / qualification','text','CDL-A, C+E, forklift certificate')}${fld('experience','Years of experience','number','5','min="0"')}</div>${checks('skills','Qualified to operate',['Car','Van','Truck','Bus','Forklift','Crane','Heavy equipment'])}<div class="two">${fld('availableFrom',available?'Available from':'Needed from','datetime-local','')}${fld('availableTo',available?'Available until':'Needed until','datetime-local','')}</div>${fld('radius','Working radius (km)','number','100','min="0"')}${fld('languages','Languages','text','English, German, Arabic')}${fld('certifications','Certificates / endorsements','text','ADR, Hazmat, tanker, forklift...')}</div>${mapWidget('location',available?'Current / work location':'Work location','Street, city, postcode or place')}`;
 if(r==='truck')return `<div class="formSection"><h3>${tr('Truck / vehicle specification')}</h3><div class="two">${sel('vehicleType','Vehicle type',['Tractor unit','Rigid truck','Van','Box truck','Reefer','Flatbed','Tanker','Tipper','Other'])}${fld('makeModel','Make / model','text','Volvo FH, Mercedes Actros...')}</div><div class="two">${fld('year','Year','number','2022')}${fld('capacity','Payload capacity','number','20000')}</div><div class="two">${sel('capacityUnit','Capacity unit',['kg','lb','pallets','m³'])}${sel('driverIncluded','Driver included?',['No','Yes'])}</div>${sel('temperatureType','Temperature capability',['Ambient','Chilled','Frozen','Multi-temperature','Not applicable'])}<div class="two">${fld('tempMin','Minimum temperature °C','number','-20')}${fld('tempMax','Maximum temperature °C','number','5')}</div><div class="two">${fld('availableFrom',available?'Available from':'Needed from','datetime-local','')}${fld('availableTo',available?'Available until':'Needed until','datetime-local','')}</div>${fld('insurance','Insurance / operating status','text','Insured, carrier authority, registration...')}</div>${mapWidget('location',available?'Vehicle location':'Where vehicle is needed','Street, depot, city or postcode')}`;
 if(r==='warehouse')return `<div class="formSection"><h3>${tr('Warehouse / storage specification')}</h3><div class="two">${sel('storageType','Storage type',['Ambient','Chilled','Frozen','Food grade','Pharma','Hazardous goods','General logistics'])}${fld('availableArea','Available / required area','number','500')}</div><div class="two">${sel('areaUnit','Area unit',['m²','ft²','pallet positions'])}${fld('pallets','Pallet positions','number','200')}</div><div class="two">${fld('tempMin','Minimum temperature °C','number','2')}${fld('tempMax','Maximum temperature °C','number','5')}</div>${checks('facilities','Facilities',['Loading docks','Forklifts','Racking','24/7 access','Security','Chilled zone','Frozen zone'])}${fld('certifications','Certifications / suitability','text','Food, pharma, HACCP, GDP...')}<div class="two">${fld('availableFrom',available?'Available from':'Needed from','date','')}${fld('availableTo',available?'Available until':'Needed until','date','')}</div></div>${mapWidget('location',available?'Warehouse location':'Preferred storage location','Street, industrial area, city or postcode')}`;
 if(r==='load')return `<div class="formSection"><h3>${tr('Load / cargo specification')}</h3><div class="two">${sel('loadType','Load type',['Full truckload','Partial / LTL','Palletised','Refrigerated','Bulk','Hazardous','Oversized','Other'])}${fld('goods','Goods / commodity','text','Food, machinery, retail goods...')}</div><div class="two">${fld('weight','Weight','number','12000')}${sel('weightUnit','Weight unit',['kg','lb','tonnes'])}</div><div class="two">${fld('pallets','Pallets','number','20')}${fld('volume','Volume m³','number','40')}</div>${sel('equipmentNeeded','Equipment needed',['Dry van','Reefer','Flatbed','Tanker','Box truck','Any suitable'])}<div class="two">${fld('tempMin','Minimum temperature °C','number','2')}${fld('tempMax','Maximum temperature °C','number','5')}</div>${fld('pickupDate',available?'Pickup date / time':'Required pickup','datetime-local','')}${fld('details','Cargo notes','text','Non-hazardous, loading requirements...')}</div>${mapWidget('pickup','Pickup location','Exact pickup address or place')}${mapWidget('delivery','Destination','Exact destination address or place')}`;
 if(r==='equipment')return `<div class="formSection"><h3>${tr('Equipment specification')}</h3><div class="two">${sel('equipmentType','Equipment type',['Forklift','Reach truck','Crane','Loader','Excavator','Pallet truck','Loading ramp','Generator','Other'])}${fld('makeModel','Make / model','text','Toyota 8FG, Linde...')}</div><div class="two">${fld('capacity','Capacity / rating','text','2.5 tonnes, 10 m reach...')}${sel('operatorIncluded','Operator included?',['No','Yes','Optional'])}</div>${fld('certifications','Inspection / certification','text','Inspection date, CE, safety certificate...')}<div class="two">${fld('availableFrom',available?'Available from':'Needed from','datetime-local','')}${fld('availableTo',available?'Available until':'Needed until','datetime-local','')}</div></div>${mapWidget('location',available?'Equipment location':'Where equipment is needed','Street, site, city or postcode')}`;
 return '';
}
function renderFields(){destroyActiveMaps();const r=$('resource').value,i=$('intent').value;$('fields').innerHTML=`<div class="hint">${tr(i==='have'?'Publish an available resource with its real specifications.':'Publish exactly what you are looking for.')}</div>`+categoryFields(r,i);$('fields').querySelectorAll('.listingMap').forEach(el=>initListingMap(el.id.replace('map_','')));translateNodeTree($('fields'))}
function setIntent(v){$('intent').value=v;$('haveBtn').classList.toggle('active',v==='have');$('needBtn').classList.toggle('active',v==='need');renderFields()}
function startListing(resource,intent){go('post');$('resource').value=resource;setIntent(intent);setTimeout(()=>$('listingTitle')?.focus(),120)}
function browseResource(resource,intent){go('market');$('filterResource').value=resource;$('filterIntent').value=intent;loadMarket()}
function togglePrice(){const m=$('priceMode').value;$('priceWrap').style.display=['request_quotes','open_bidding'].includes(m)?'none':'block'}
async function submitListing(){if(!me){go('accountPane');return}const data={};$('fields').querySelectorAll('[data-k]').forEach(el=>data[el.dataset.k]=el.type==='number'?Number(el.value||0):el.value);$('fields').querySelectorAll('[data-check-key]').forEach(fs=>data[fs.dataset.checkKey]=[...fs.querySelectorAll('input:checked')].map(x=>x.value).join(', '));try{await api('/api/listings',{method:'POST',body:JSON.stringify({intent:$('intent').value,resource:$('resource').value,title:$('listingTitle').value,country:$('listingCountry').value,currency:$('currency').value,priceMode:$('priceMode').value,price:Number($('price').value||0),data})});$('postMsg').textContent='Published successfully.';loadMarket()}catch(e){$('postMsg').textContent=e.message}}
function listingLabel(x){return `${x.intent==='have'?tr('AVAILABLE'):tr('WANTED')} · ${tr(({driver:'Driver',truck:'Truck',load:'Load',warehouse:'Warehouse',equipment:'Equipment'})[x.resource]||x.resource.toUpperCase())}`}
function priceText(x){if(x.priceMode==='request_quotes')return'Request quotes';if(x.priceMode==='open_bidding')return'Open bidding';if(x.priceMode==='negotiable')return x.price?`${x.currency} ${x.price} · negotiable`:'Negotiable';return`${x.currency} ${x.price}`}
function summary(x){const d=x.data||{};if(x.resource==='driver')return `${d.location||'—'} · ${d.licenseClass||'—'} · ${d.availableFrom||'—'}`;if(x.resource==='truck')return `${d.location||'—'} · ${d.vehicleType||'—'} · ${d.capacity||'—'} ${d.capacityUnit||''}`;if(x.resource==='load')return `${d.pickup||'—'} → ${d.delivery||'—'} · ${d.weight||'—'} ${d.weightUnit||''}`;if(x.resource==='warehouse')return `${d.location||'—'} · ${d.storageType||'—'} · ${d.availableArea||'—'} ${d.areaUnit||''}`;if(x.resource==='equipment')return `${d.location||'—'} · ${d.equipmentType||'—'} · ${d.capacity||'—'}`;return d.location||'—'}
async function loadMarket(){const j=await api('/api/listings');listings=j.listings;const fi=$('filterIntent')?.value||'',fr=$('filterResource')?.value||'',fc=($('filterCountry')?.value||'').toLowerCase();const rows=listings.filter(x=>(!fi||x.intent===fi)&&(!fr||x.resource===fr)&&(!fc||(x.country||'').toLowerCase().includes(fc)));$('marketList').innerHTML=rows.length?rows.map(x=>`<article class="card marketCard"><div class="row"><span class="tag">${listingLabel(x)}</span>${x.user?.verified?'<span class="verified">✓ Verified</span>':''}</div><h3>${esc(x.title||listingLabel(x))}</h3><p>${esc(summary(x))}</p><p class="price">${esc(priceText(x))}</p><small>${esc(x.country||'')} · by ${esc(x.user?.name||'Member')}</small><div class="actions">${me&&me.id!==x.userId?`<button class="goldBtn mini" onclick="openOffer('${x.id}','${x.currency}')">Make offer</button>`:''}${me&&me.id===x.userId?`<button class="outlineBtn mini" onclick="closeListing('${x.id}')">Close</button>`:''}</div><div id="offer_${x.id}"></div></article>`).join(''):'<div class="card">No open listings match these filters.</div>'}
function openOffer(id,currency){if(!me){go('accountPane');return}$('offer_'+id).innerHTML=`<div class="offerBox"><input id="oa_${id}" type="number" placeholder="Amount"><input id="om_${id}" placeholder="Message / terms"><button class="goldBtn mini" onclick="sendOffer('${id}','${currency}')">Send offer</button></div>`}
async function sendOffer(id,currency){try{await api('/api/offers',{method:'POST',body:JSON.stringify({listingId:id,amount:Number($('oa_'+id).value),currency,message:$('om_'+id).value})});$('offer_'+id).innerHTML='<div class="msg">Offer sent.</div>'}catch(e){$('offer_'+id).innerHTML=`<div class="msg">${esc(e.message)}</div>`}}
async function closeListing(id){await api('/api/listings/'+id,{method:'DELETE'});loadMarket()}
async function loadMatches(){const j=await api('/api/matches');$('matchList').innerHTML=j.matches.length?j.matches.slice(0,50).map(m=>`<article class="card ${m.kind==='load_truck_driver'?'combo':''}"><div class="score">${m.score}/100</div><h3>${m.kind==='load_truck_driver'?'Load + Truck + Driver':'Potential match'}</h3>${m.listings.map(x=>`<p><b>${listingLabel(x)}</b><br>${esc(summary(x))}</p>`).join('')}</article>`).join(''):'<div class="card">No matches yet.</div>'}
async function loadOffers(){if(!me){$('offerList').innerHTML='<div class="card">Login to view offers.</div>';return}const j=await api('/api/offers');$('offerList').innerHTML=j.offers.length?j.offers.map(o=>`<article class="card"><span class="tag">${esc(o.status)}</span><h3>${o.currency} ${o.amount}</h3><p>${esc(o.message||'No message')}</p>${o.status==='pending'&&o.toUserId===me.id?`<div class="actions"><button class="goldBtn mini" onclick="offerAction('${o.id}','accept')">Accept</button><button class="outlineBtn mini" onclick="counterOffer('${o.id}')">Counter</button><button class="linkBtn" onclick="offerAction('${o.id}','reject')">Reject</button></div>`:''}<div id="counter_${o.id}"></div></article>`).join(''):'<div class="card">No offers yet.</div>'}
async function offerAction(id,action){await api(`/api/offers/${id}/${action}`,{method:'POST',body:'{}'});loadOffers();loadBookings();loadMarket()}
function counterOffer(id){$('counter_'+id).innerHTML=`<div class="offerBox"><input id="ca_${id}" type="number" placeholder="Counter amount"><input id="cm_${id}" placeholder="Terms"><button class="goldBtn mini" onclick="sendCounter('${id}')">Send counter</button></div>`}
async function sendCounter(id){await api(`/api/offers/${id}/counter`,{method:'POST',body:JSON.stringify({amount:Number($('ca_'+id).value),message:$('cm_'+id).value})});loadOffers()}
async function loadBookings(){if(!me){$('bookingList').innerHTML='';return}const j=await api('/api/bookings');$('bookingList').innerHTML=j.bookings.length?j.bookings.map(b=>`<article class="card"><span class="tag">AGREED</span><h3>${b.currency} ${b.agreedPrice}</h3><p>TUT Move fee: ${b.platformFeePct}% = ${b.currency} ${b.platformFee}</p><p>Provider net: ${b.currency} ${b.providerNet}</p><p class="muted">Payment status: ${b.paymentStatus} — payment provider not connected yet.</p></article>`).join(''):'<div class="card">No agreed bookings yet.</div>'}
function fileData(id){return new Promise((resolve,reject)=>{const f=$(id).files[0];if(!f)return resolve(null);if(f.size>3e6)return reject(new Error('Each file must be 3MB or less.'));const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)})}
async function submitVerification(){if(!me){go('accountPane');return}try{const [license,identity,selfie]=await Promise.all([fileData('licenseFile'),fileData('identityFile'),fileData('selfieFile')]);const j=await api('/api/verification',{method:'POST',body:JSON.stringify({country:$('verifyCountry').value,licenseNumber:$('licenseNumber').value,licenseClass:$('licenseClass').value,expiry:$('licenseExpiry').value,files:{license,identity,selfie}})});me=j.user;renderAccount();$('verifyMsg').innerHTML=`Status: <b>${esc(j.verification.status)}</b><br>${esc(j.verification.message)}`}catch(e){$('verifyMsg').textContent=e.message}}
async function loadVerification(){if(!me){$('verifyMsg').textContent='Login first.';return}const j=await api('/api/verification');if(j.verification)$('verifyMsg').innerHTML=`Current status: <b>${esc(j.verification.status)}</b><br>${esc(j.verification.message||'')}`}
async function loadAdmin(){if(!me||me.role!=='owner')return;const j=await api('/api/admin/summary');$('feePct').value=j.settings.platformFeePct;$('defaultCurrency').value=j.settings.defaultCurrency;for(const k of ['brandName','siteUrl','ownerName','ownerEmail','legalEntity','supportEmail']){if($(k))$(k).value=j.settings[k]||'';}const s=j.stats;$('adminArea').innerHTML=`<div class="kpis"><div class="kpi"><span>Users</span><b>${s.users}</b></div><div class="kpi"><span>Open listings</span><b>${s.openListings}</b></div><div class="kpi"><span>Offers</span><b>${s.offers}</b></div><div class="kpi"><span>Bookings</span><b>${s.bookings}</b></div><div class="kpi"><span>Platform revenue*</span><b>${s.platformRevenue}</b></div></div><p class="muted">*Calculated from agreed bookings only; no real payment has been captured in this MVP.</p><h2 class="subhead">Users</h2><div class="cards">${j.users.map(u=>`<div class="card"><h3>${esc(u.name)}</h3><p>${esc(u.email)}</p><p>${esc((u.roles||[]).join(', '))} · ${esc(u.country||'')}</p><span class="tag">${esc(u.verificationStatus)}</span></div>`).join('')}</div><h2 class="subhead">Recent bookings</h2><div class="cards">${j.bookings.slice(-20).reverse().map(b=>`<div class="card"><h3>${b.currency} ${b.agreedPrice}</h3><p>Fee ${b.platformFeePct}% = ${b.currency} ${b.platformFee}</p><span class="tag">${b.status}</span></div>`).join('')||'<div class="card">No bookings yet.</div>'}</div>`}
async function saveOwnership(){const body={brandName:$('brandName').value,siteUrl:$('siteUrl').value,ownerName:$('ownerName').value,ownerEmail:$('ownerEmail').value,legalEntity:$('legalEntity').value,supportEmail:$('supportEmail').value};const j=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(body)});alert('Ownership settings saved for '+(j.settings.siteUrl||'TUT Move'));}
async function saveSettings(){const j=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({platformFeePct:Number($('feePct').value),defaultCurrency:$('defaultCurrency').value})});alert(`Saved: ${j.settings.platformFeePct}%`) }

const tutObserver=new MutationObserver(muts=>{
  for(const m of muts) for(const n of m.addedNodes){
    if(n.nodeType===1) translateNodeTree(n);
    else if(n.nodeType===3 && n.parentElement) translateNodeTree(n.parentElement);
  }
});
window.addEventListener('DOMContentLoaded',()=>{tutObserver.observe(document.body,{childList:true,subtree:true});refreshLanguage();});

init();
